def min_swaps_to_equalize(str1, str2):
    if str1 == str2:
        return 0

    m, n = len(str1), len(str2)
    if m != n:
        return -1  # Strings of different lengths cannot be made equal by swapping

    # Count the number of 1s and 0s that need to be swapped
    diff1 = sum(c1 != c2 for c1, c2 in zip(str1, str2))
    diff0 = m - diff1

    # Minimum swaps will be the minimum of swaps needed to make all 1s match and all 0s match
    return min(diff1, diff0)
