    """
    Choose points from two ranges such that no point lies in both ranges.

    Args:
    range1_start (int): Start of the first range (inclusive).
    range1_end (int): End of the first range (inclusive).
    range2_start (int): Start of the second range (inclusive).
    range2_end (int): End of the second range (inclusive).

    Returns:
    tuple: Two integers, first is a point from the first range and second is from the second range such that
           they do not overlap. If no such points exist, returns (-1, -1).
    """
    # Ensure range1_start is less than range1_end
    if range1_start > range1_end:
        return (-1, -1)
    # Ensure range2_start is less than range2_end
    if range2_start > range2_end:
        return (-1, -1)

    # Case 1: Ranges do not overlap
    if range1_end < range2_start or range2_end < range1_start:
        return (range1_start, range2_start)

    # Case 2: Ranges overlap
    # Choose a point from range1 that is not in range2
    if range1_start < range2_start:
        point_from_range1 = range1_end
    else:
        point_from_range1 = range1_start

    # Choose a point from range2 that is not in range1
    if range2_start < range1_start:
        point_from_range2 = range2_end
