def max_segments(n, a, b, c):
    # Initialize the count of segments
    count = 0

    # Try to use as many segments of length 'a' as possible
    for i in range(n // a, -1, -1):
        remaining_after_a = n - (a * i)
        # Check if the remaining can be divided by b or c
        if remaining_after_a % b == 0:
            count = max(count, i + remaining_after_a // b)
        elif remaining_after_a % c == 0:
            count = max(count, i + remaining_after_a // c)
        # Try combination of b and c
        for j in range(remaining_after_a // b, -1, -1):
            remaining_after_b = remaining_after_a - (b * j)
            if remaining_after_b % c == 0:
                count = max(count, i + j + remaining_after_b // c)

    return count
