from functools import lru_cache

def palindrome_partition(s: str, k: int) -> int:
    n = len(s)

    # Function to count changes needed to make a substring palindrome
    @lru_cache(None)
    def count_changes(start, end):
        if start >= end:
            return 0
        changes = 0
        while start < end:
            if s[start] != s[end]:
                changes += 1
            start += 1
            end -= 1
        return changes

    # DP table where dp[i][j] is the minimum changes needed to partition s[:i] into j palindromes
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            for p in range(i):
                dp[i][j] = min(dp[i][j], dp[p][j - 1] + count_changes(p, i - 1))

    return dp[n][k]

# Example usage
print(palindrome_partition("abc", 2))  # Output: 1
print(palindrome_partition("aabbc", 3))  # Output: 0
print(palindrome_partition("leetcode", 8))  # Output: 0
