def minCost(grid):
    m, n = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    sign_to_dir = {1: 0, 2: 1, 3: 2, 4: 3}

    def get_next(x, y, sign):
        dx, dy = directions[sign - 1]
        nx, ny = x + dx, y + dy
        if 0 <= nx < m and 0 <= ny < n:
            return nx, ny
        return None

    def bfs(start, end):
        queue = deque([(0, start)])
        visited = set([start])
        while queue:
            cost, (x, y) = heapq.heappop(queue)
            if (x, y) == end:
                return cost
            for sign in range(1, 5):
                nx, ny = get_next(x, y, sign)
                if nx is not None and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    next_cost = cost + (sign != sign_to_dir[grid[x][y]])
                    heapq.heappush(queue, (next_cost, (nx, ny)))
        return float('inf')

    return bfs((0, 0), (m - 1, n - 1))
