def findMedianSortedArrays(nums1, nums2):
    def findKthElement(A, a_idx, B, b_idx, k):
        if a_idx >= len(A):
            return B[b_idx + k - 1]
        if b_idx >= len(B):
            return A[a_idx + k - 1]
        if k == 1:
            return min(A[a_idx], B[b_idx])

        a_mid = float('inf') if a_idx + k // 2 - 1 >= len(A) else A[a_idx + k // 2 - 1]
        b_mid = float('inf') if b_idx + k // 2 - 1 >= len(B) else B[b_idx + k // 2 - 1]

        if a_mid < b_mid:
            return findKthElement(A, a_idx + k // 2, B, b_idx, k - k // 2)
        else:
            return findKthElement(A, a_idx, B, b_idx + k // 2, k - k // 2)

    total_length = len(nums1) + len(nums2)
    if total_length % 2 == 1:
        return findKthElement(nums1, 0, nums2, 0, total_length // 2 + 1)
    else:
        return (findKthElement(nums1, 0, nums2, 0, total_length // 2) + 
                findKthElement(nums1, 0, nums2, 0, total_length // 2 + 1)) / 2

