from collections import deque
from bisect import bisect_left
from typing import List, Tuple

def dfs(tree: List[List[Tuple[int, int]]], a: List[int], start: int, parent: int) -> List[int]:
    sequence = [a[start]]
    for child, _ in tree[start]:
        if child != parent:
            sequence.extend(dfs(tree, a, child, start))
    return sequence

def longest_increasing_subsequence(sequence: List[int]) -> int:
    lis = []
    for num in sequence:
        idx = bisect_left(lis, num)
        if idx == len(lis):
            lis.append(num)
        else:
            lis[idx] = num
    return len(lis)

def solve_tree_lis(n: int, a: List[int], edges: List[Tuple[int, int]]) -> None:
    tree = [[] for _ in range(n)]
    for u, v in edges:
        tree[u-1].append((v-1, 0))
        tree[v-1].append((u-1, 0))

    def dfs_lis(start: int, parent: int) -> None:
        sequence = dfs(tree, a, start, parent)
        lis_length = longest_increasing_subsequence(sequence)
        print(lis_length)
        for child, _ in tree[start]:
            if child != parent:
                for _ in range(lis_length):
                    tree[child].append((0, 0))
                dfs_lis(child, start)

    dfs_lis(0, -1)

