            if grid[i][j] == '@':
                start = (i, j, 0)  # (row, col, collected_keys)
            elif grid[i][j].islower():
                keys |= 1 << (ord(grid[i][j]) - ord('a'))

    queue = deque([start])
    visited = set([start])
    steps = 0

    while queue:
        for _ in range(len(queue)):
            r, c, collected_keys = queue.popleft()

            if collected_keys == keys:
                return steps

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    cell = grid[nr][nc]
                    if cell == '#':
