                    if cell.isupper() and not (collected_keys & (1 << (ord(cell.lower()) - ord('a')))):
                        continue
                    if (nr, nc, collected_keys) not in visited:
                        visited.add((nr, nc, collected_keys))
                        if cell.islower():
                            queue.append((nr, nc, collected_keys | 1 << (ord(cell) - ord('a'))))
                        else:
                            queue.append((nr, nc, collected_keys))
        steps += 1

