def min_candies(ratings):
    n = len(ratings)
    if n == 0:
        return 0

    # Initialize candies array with 1 candy for each child
    candies = [1] * n

    # Forward pass: ensure right neighbor has more candy if rating is higher
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            candies[i] = candies[i - 1] + 1

    # Backward pass: ensure left neighbor has more candy if rating is higher
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            candies[i] = max(candies[i], candies[i + 1] + 1)

    # Sum up the candies to get the total minimum candies required
    return sum(candies)

