from functools import lru_cache

def getLengthOfOptimalCompression(s: str, k: int) -> int:
    @lru_cache(None)
    def dp(i, last_char, last_count, remaining_deletions):
        if remaining_deletions < 0:
            return float('inf')
        if i == len(s):
            return 0

        # Option 1: Keep the current character
        keep = 1 + dp(i + 1, last_char, last_count + (s[i] == last_char), remaining_deletions)

        # Option 2: Delete the current character
        delete = dp(i + 1, last_char, last_count, remaining_deletions - 1)

        # Option 3: Replace the current character with a new one
        for new_char in set(s[i+1:]) - {last_char}:
            replace = 1 + dp(i + 1, new_char, 1, remaining_deletions)
            keep = min(keep, replace)

        return min(keep, delete)

    return dp(0, '', 0, k)
```

