from functools import lru_cache

class Solution:
    def numberWays(self, hats: List[List[int]]) -> int:
        MOD = 10**9 + 7
        n = len(hats)

        # Create a mapping from hat to people who like it
        hat_to_people = defaultdict(set)
        for i, hat_list in enumerate(hats):
            for hat in hat_list:
                hat_to_people[hat].add(i)

