def longest_palindrome(text: str) -> int:
    n = len(text)
    dp = [[False] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = True
    max_k = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if length == 2:
                dp[i][j] = text[i] == text[j]
            else:
                dp[i][j] = text[i] == text[j] and dp[i + 1][j - 1]
            if dp[i][j] and length > max_k:
                max_k = length
    return max_k

