def numBusesToDestination(routes, S, T):
    if S == T:
        return 0

    # Create a graph where each bus stop points to the buses that pass through it
    stop_to_buses = defaultdict(set)
    for i, route in enumerate(routes):
        for stop in route:
            stop_to_buses[stop].add(i)

    # BFS to find the shortest path
    queue = deque([(S, 0)])  # (current stop, number of buses taken)
    visited_stops = set([S])
    visited_buses = set()

    while queue:
        current_stop, buses_taken = queue.popleft()

        for bus in stop_to_buses[current_stop]:
            if bus in visited_buses:
                continue
            visited_buses.add(bus)
            for stop in routes[bus]:
                if stop == T:
                    return buses_taken + 1
                if stop not in visited_stops:
                    visited_stops.add(stop)
                    queue.append((stop, buses_taken + 1))

