def min_steps_to_valid_grid(grid):
    n = len(grid)
    steps = 0

    for col in range(n):
        count_ones = 0
        for row in range(n):
            if grid[row][col] == 1:
                count_ones += 1
            if count_ones > 1:
                return -1
            if count_ones == 1 and row > col:
                return -1

        if count_ones == 0:
            continue

        row_with_one = -1
        for row in range(n):
            if grid[row][col] == 1:
                row_with_one = row
                break

        while row_with_one > col:
            grid[row_with_one], grid[row_with_one - 1] = grid[row_with_one - 1], grid[row_with_one]
            steps += 1
            row_with_one -= 1

    return steps

