def maxLength(arr: List[str]) -> int:
    def backtrack(index, current):
        if index == len(arr):
            return len(current)

        # Skip the current string if it has duplicate characters
        if len(set(arr[index])) < len(arr[index]):
            return backtrack(index + 1, current)

        # Include the current string and check
        include = backtrack(index + 1, current + arr[index])

        # Exclude the current string and check
        exclude = backtrack(index + 1, current)

        # Return the maximum length found
        return max(include, exclude)

