def count_path_configurations(Q, queries):
    def count_pairs(n, u, v):
        if u == v:
            return n * n
        u_path = []
        v_path = []
        while u != 1:
            if u % 2 == 0:
                u_path.append('L')
                u //= 2
            else:
                u_path.append('R')
                u = (u - 1) // 2
        while v != 1:
            if v % 2 == 0:
                v_path.append('L')
                v //= 2
            else:
                v_path.append('R')
                v = (v - 1) // 2
        u_path.reverse()
        v_path.reverse()
        if u_path != v_path:
            return 0
        common_length = len(u_path)
        u = n
        v = n
        for i in range(common_length):
