from heapq import heappush, heappop

def minInteger(num: str, k: int) -> str:
    n = len(num)
    if k >= n * (n - 1) // 2:
        return ''.join(sorted(num))

    result = []
    count = [0] * 10
    for digit in num:
        count[int(digit)] += 1

    min_heap = []
    for i in range(10):
        if count[i] > 0:
            heappush(min_heap, (i, count[i]))

    for _ in range(n):
        while k < 0 or not min_heap:
            result.append(str(min_heap[0][0]))
            count[min_heap[0][0]] -= 1
            if count[min_heap[0][0]] == 0:
                heappop(min_heap)
            k += 1
        digit, _ = heappop(min_heap)
        result.append(str(digit))
        k -= n - 1 - num.index(str(digit))

    return ''.join(result)

