def evaluate(expression):
    def parse(expr):
        stack, i = [], 0
        while i < len(expr):
            if expr[i] == '(':
                stack.append(i)
            elif expr[i] == ')':
                start = stack.pop()
                yield expr[start+1:i]
                i += 1
            elif expr[i] in '()':
                i += 1
            else:
                j = i
                while j < len(expr) and expr[j] not in ' ()':
                    j += 1
                yield expr[i:j]
                i = j
        yield None

    def eval_expr(expr, env):
        if expr.isdigit() or (expr[0] == '-' and expr[1:].isdigit()):
            return int(expr)
        if expr[0] == '(':
            if expr[1:5] == 'add ':
                return eval_expr(expr[5:-1].split(' ')[0], env) + eval_expr(expr[5:-1].split(' ')[1], env)
            elif expr[1:6] == 'mult ':
                return eval_expr(expr[6:-1].split(' ')[0], env) * eval_expr(expr[6:-1].split(' ')[1], env)
            elif expr[1:4] == 'let':
                let_env = env.copy()
                for var, val in zip(expr[4:-1].split(' ')[::2], expr[4:-1].split(' ')[1::2]):
                    let_env[var] = eval_expr(val, let_env)
                return eval_expr(expr[-1], let_env)
        return env[expr]

    tokens = list(parse(expression))
    env = {}
    for token in tokens[:-1]:
        if token[0] == 'let':
            for var, val in zip(token[1::2], token[2::2]):
                env[var] = eval_expr(val, env)
        else:
            env[token[0]] = eval_expr(token[1], env)
    return eval_expr(tokens[-1], env)

