def orderly_queue(s: str, k: int) -> str:
    if k > 1:
        # If k > 1, we can sort the string lexicographically
        return ''.join(sorted(s))
    else:
        # If k == 1, we need to find the smallest rotation
        n = len(s)
        current_min = s
        for i in range(n):
            s = s[1:] + s[0]  # Rotate the string
            if s < current_min:
                current_min = s
        return current_min

