def max_sum_divisible_by_three(nums: List[int]) -> int:
    @lru_cache(maxsize=None)
    def dp(index, remainder):
        if index == len(nums):
            return 0 if remainder == 0 else float('-inf')
        # Option 1: Skip the current number
        skip = dp(index + 1, remainder)
        # Option 2: Take the current number if it doesn't change the remainder
        take = dp(index + 1, (remainder - nums[index] % 3) % 3) + nums[index]
        return max(skip, take)

