def max_candies(N, K, x, D, p):
    # Check if the given sequence can be extended to satisfy all conditions
    def is_valid_sequence(p, D):
        for i in range(K):
            if any(abs(p[i] - p[j]) > D for j in range(K) if i != j):
                return False
        return True

    # Calculate the maximum possible total number of candies
    def max_possible_candies():
        max_candies = 0
        for i in range(K, N):
            # Find the smallest and largest possible values for the next student
            min_val = max(p[0], p[-1] - D)
            max_val = min(x, p[-1] + D)
            if min_val > max_val:
                return -1
            max_candies += max_val
            p.append(max_val)
        return max_candies

    # Sort the known sequence to facilitate the search for valid sequences
    p.sort()
    if not is_valid_sequence(p, D):
        return -1

    return max_possible_candies()

